20	/**
21	 * The StaticPHPDriver calls a static loadMetadata() method on your entity
22	 * classes where you can manually populate the ClassMetadata instance.
23	 */
24	class StaticPHPDriver implements MappingDriver
25	{
26	    /**
27	     * Paths of entity directories.
28	     *
29	     * @var array<int, string>
30	     */
31	    private array $paths = [];
32	
33	    /**
34	     * Map of all class names.
35	     *
36	     * @var array<int, string>
37	     * @phpstan-var list<class-string>
38	     */
39	    private array|null $classNames = null;
40	
41	    /** @param array<int, string>|string $paths */
42	    public function __construct(array|string $paths)
43	    {
44	        $this->addPaths((array) $paths);
45	    }
46	
47	    /** @param array<int, string> $paths */
48	    public function addPaths(array $paths): void
49	    {
50	        $this->paths = array_unique([...$this->paths, ...$paths]);
51	    }
52	
53	    public function loadMetadataForClass(string $className, ClassMetadata $metadata): void
54	    {
55	        $className::loadMetadata($metadata);
56	    }
57	
58	    /**
59	     * {@inheritDoc}
60	     *
61	     * @todo Same code exists in ColocatedMappingDriver, should we re-use it
62	     * somehow or not worry about it?
63	     */
64	    public function getAllClassNames(): array
65	    {
66	        if ($this->classNames !== null) {
67	            return $this->classNames;
68	        }
69	
70	        if ($this->paths === []) {
71	            throw MappingException::pathRequiredForDriver(static::class);
72	        }
73	
74	        $classes       = [];
75	        $includedFiles = [];
76	
77	        foreach ($this->paths as $path) {
78	            if (! is_dir($path)) {
79	                throw MappingException::fileMappingDriversRequireConfiguredDirectoryPath($path);
80	            }
81	
82	            $iterator = new RecursiveIteratorIterator(
83	                new RecursiveDirectoryIterator($path),
84	                RecursiveIteratorIterator::LEAVES_ONLY,
85	            );
86	
87	            foreach ($iterator as $file) {
88	                if ($file->getBasename('.php') === $file->getBasename()) {
89	                    continue;
90	                }
91	
92	                $sourceFile = realpath($file->getPathName());
93	                require_once $sourceFile;
94	                $includedFiles[] = $sourceFile;
95	            }
96	        }
97	
98	        $declared = get_declared_classes();
99	
100	        foreach ($declared as $className) {
101	            $rc = new ReflectionClass($className);
102	
103	            $sourceFile = $rc->getFileName();
104	
105	            if (! in_array($sourceFile, $includedFiles, true) || $this->isTransient($className)) {
106	                continue;
107	            }
108	
109	            $classes[] = $className;
110	        }
111	
112	        $this->classNames = $classes;
113	
114	        return $classes;
115	    }
116	
117	    public function isTransient(string $className): bool
118	    {
119	        return ! method_exists($className, 'loadMetadata');
120	    }
121	}
